#include <bits/stdc++.h>
#define inf 17446744073709551616ull
#define ll unsigned long long
using namespace std;
ll mod,dp[18][250005];
ll fac[250005],inv[250005];
ll n,k;
inline ll qpow(ll a,ll b)
{ll res=1ll,tp=a;
while (b)
{if (b&1ll) {res*=tp;res%=mod;}
tp*=tp;tp%=mod;b>>=1ll;
}
return res;
}
inline ll cal(int a,int b)
{return (((fac[a]*inv[b])%mod)*inv[a-b])%mod;}
inline ll calc()
{int i,j,l;
fac[0]=1ll;
for (i=1;i<=n;i++) fac[i]=fac[i-1]*((ll)(i))%mod;
inv[n]=qpow(fac[n],mod-2ll);
for (i=n-1;i>=0;i--) inv[i]=inv[i+1]*((ll)(i+1))%mod;
for (i=1;i<=n;i++) {dp[1][i]=inv[i];}
ll ans=dp[1][n]*cal(k,1)%mod;
int t=min(17,((int)(k)));
for (i=2;i<=t;i++)
{for (j=n;j;j=(j-1)&n)
{for (l=j;l;l=(l-1)&j)
{dp[i][j]+=dp[i-1][j^l]*inv[l];
if (dp[i][j]>inf) 
dp[i][j]%=mod;
}
dp[i][j]%=mod;
}
ans+=dp[i][n]*cal(k,i);
ans%=mod;
}
ans*=fac[n];ans%=mod;
return ans;
}
int main (){
	cin>>n>>k>>mod;
	ll ans=qpow(k,n);
	if (n&1) 
	{cout<<ans<<endl;
	return 0;
	}
	ans=(ans-calc()+mod)%mod;
	cout<<ans<<endl;
	return 0;
}

